  UPDATE public.biblioteca_vectores SET revision_pendiente = false, es_norma_vigente = NULL,
    metadata = (metadata - 'rol' - 'clasificacion_propuesta') || jsonb_build_object('estado_v', 'V5', 'vigencia', 'PENDIENTE_CLO', 'revision_pendiente', false, 'motivo_rol', 'PENDIENTE_CLO: la edición PJ 2014 lo da por derogado (D.35-2013) pero el art. 14 del D.35-2013 (Gaceta 33,222) no lo lista (D5)', 'adjudicacion', 'EXPEDIENTE_AUDITORIA_CC_OLA4.md (D1–D8)', 'rol', 'CONTEXT', 'promocion_fecha', '2026-11-24', 'promocion_ola', 'OLA4')
  WHERE ingest_batch = 'OLA4_CC_2014_01' AND id IN ('OLA4_CC_2014_01:CODIGO_CIVIL:307', 'OLA4_CC_2014_01:CODIGO_CIVIL:397');
  UPDATE public.biblioteca_vectores SET revision_pendiente = false, es_norma_vigente = false,
    metadata = (metadata - 'rol' - 'clasificacion_propuesta') || jsonb_build_object('estado_v', 'V5', 'vigencia', 'DEROGADO', 'revision_pendiente', false, 'motivo_rol', 'DEROGADO por D.211-2006 según la nota de la edición PJ 2014; cotejo con La Gaceta pendiente (D1)', 'adjudicacion', 'EXPEDIENTE_AUDITORIA_CC_OLA4.md (D1–D8)', 'rol', 'CONTEXT', 'promocion_fecha', '2026-11-24', 'promocion_ola', 'OLA4')
  WHERE ingest_batch = 'OLA4_CC_2014_01' AND id IN ('OLA4_CC_2014_01:CODIGO_CIVIL:513', 'OLA4_CC_2014_01:CODIGO_CIVIL:514', 'OLA4_CC_2014_01:CODIGO_CIVIL:515', 'OLA4_CC_2014_01:CODIGO_CIVIL:517', 'OLA4_CC_2014_01:CODIGO_CIVIL:1495', 'OLA4_CC_2014_01:CODIGO_CIVIL:1496', 'OLA4_CC_2014_01:CODIGO_CIVIL:1497', 'OLA4_CC_2014_01:CODIGO_CIVIL:1498', 'OLA4_CC_2014_01:CODIGO_CIVIL:1499', 'OLA4_CC_2014_01:CODIGO_CIVIL:1500', 'OLA4_CC_2014_01:CODIGO_CIVIL:1501', 'OLA4_CC_2014_01:CODIGO_CIVIL:1502', 'OLA4_CC_2014_01:CODIGO_CIVIL:1503', 'OLA4_CC_2014_01:CODIGO_CIVIL:1504', 'OLA4_CC_2014_01:CODIGO_CIVIL:1505', 'OLA4_CC_2014_01:CODIGO_CIVIL:1506', 'OLA4_CC_2014_01:CODIGO_CIVIL:1507', 'OLA4_CC_2014_01:CODIGO_CIVIL:1508', 'OLA4_CC_2014_01:CODIGO_CIVIL:1509', 'OLA4_CC_2014_01:CODIGO_CIVIL:1510', 'OLA4_CC_2014_01:CODIGO_CIVIL:1511', 'OLA4_CC_2014_01:CODIGO_CIVIL:1512', 'OLA4_CC_2014_01:CODIGO_CIVIL:1513', 'OLA4_CC_2014_01:CODIGO_CIVIL:1514', 'OLA4_CC_2014_01:CODIGO_CIVIL:1515', 'OLA4_CC_2014_01:CODIGO_CIVIL:1516', 'OLA4_CC_2014_01:CODIGO_CIVIL:1517', 'OLA4_CC_2014_01:CODIGO_CIVIL:1518', 'OLA4_CC_2014_01:CODIGO_CIVIL:1519', 'OLA4_CC_2014_01:CODIGO_CIVIL:1520', 'OLA4_CC_2014_01:CODIGO_CIVIL:1521', 'OLA4_CC_2014_01:CODIGO_CIVIL:1522', 'OLA4_CC_2014_01:CODIGO_CIVIL:1523', 'OLA4_CC_2014_01:CODIGO_CIVIL:1524', 'OLA4_CC_2014_01:CODIGO_CIVIL:1525', 'OLA4_CC_2014_01:CODIGO_CIVIL:1526', 'OLA4_CC_2014_01:CODIGO_CIVIL:1527', 'OLA4_CC_2014_01:CODIGO_CIVIL:1528', 'OLA4_CC_2014_01:CODIGO_CIVIL:1529', 'OLA4_CC_2014_01:CODIGO_CIVIL:1530', 'OLA4_CC_2014_01:CODIGO_CIVIL:1531', 'OLA4_CC_2014_01:CODIGO_CIVIL:1532', 'OLA4_CC_2014_01:CODIGO_CIVIL:1533', 'OLA4_CC_2014_01:CODIGO_CIVIL:1534', 'OLA4_CC_2014_01:CODIGO_CIVIL:1535', 'OLA4_CC_2014_01:CODIGO_CIVIL:1536', 'OLA4_CC_2014_01:CODIGO_CIVIL:1537', 'OLA4_CC_2014_01:CODIGO_CIVIL:1538', 'OLA4_CC_2014_01:CODIGO_CIVIL:2158', 'OLA4_CC_2014_01:CODIGO_CIVIL:2367');
  UPDATE public.biblioteca_vectores SET revision_pendiente = false, es_norma_vigente = true,
    metadata = (metadata - 'rol' - 'clasificacion_propuesta') || jsonb_build_object('estado_v', 'V5', 'vigencia', 'TRUE_PRESUNTA', 'revision_pendiente', false, 'motivo_rol', 'PRIMARY elegible (párrafo derogado anotado): edición consolidada del Poder Judicial (2014) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)', 'adjudicacion', 'EXPEDIENTE_AUDITORIA_CC_OLA4.md (D1–D8)', 'promocion_fecha', '2026-11-24', 'promocion_ola', 'OLA4')
  WHERE ingest_batch = 'OLA4_CC_2014_01' AND id IN ('OLA4_CC_2014_01:CODIGO_CIVIL:553', 'OLA4_CC_2014_01:CODIGO_CIVIL:2141');
  UPDATE public.biblioteca_vectores SET revision_pendiente = false, es_norma_vigente = false,
    metadata = (metadata - 'rol' - 'clasificacion_propuesta') || jsonb_build_object('estado_v', 'V5', 'vigencia', 'DEROGADO', 'revision_pendiente', false, 'motivo_rol', 'DEROGADO por D.51-2011 según la nota de la edición PJ 2014; cotejo con La Gaceta pendiente (D1)', 'adjudicacion', 'EXPEDIENTE_AUDITORIA_CC_OLA4.md (D1–D8)', 'rol', 'CONTEXT', 'promocion_fecha', '2026-11-24', 'promocion_ola', 'OLA4')
  WHERE ingest_batch = 'OLA4_CC_2014_01' AND id IN ('OLA4_CC_2014_01:CODIGO_CIVIL:1565');
  UPDATE public.biblioteca_vectores SET revision_pendiente = false, es_norma_vigente = false,
    metadata = (metadata - 'rol' - 'clasificacion_propuesta') || jsonb_build_object('estado_v', 'V5', 'vigencia', 'DEROGADO', 'revision_pendiente', false, 'motivo_rol', 'DEROGADO por D.161-2000 según la nota de la edición PJ 2014; cotejo con La Gaceta pendiente (D1)', 'adjudicacion', 'EXPEDIENTE_AUDITORIA_CC_OLA4.md (D1–D8)', 'rol', 'CONTEXT', 'promocion_fecha', '2026-11-24', 'promocion_ola', 'OLA4')
  WHERE ingest_batch = 'OLA4_CC_2014_01' AND id IN ('OLA4_CC_2014_01:CODIGO_CIVIL:2019', 'OLA4_CC_2014_01:CODIGO_CIVIL:2020');
  UPDATE public.biblioteca_vectores SET revision_pendiente = false, es_norma_vigente = false,
    metadata = (metadata - 'rol' - 'clasificacion_propuesta') || jsonb_build_object('estado_v', 'V5', 'vigencia', 'DEROGADO', 'revision_pendiente', false, 'motivo_rol', 'DEROGADO por D.69/1937 según la nota de la edición PJ 2014; cotejo con La Gaceta pendiente (D1)', 'adjudicacion', 'EXPEDIENTE_AUDITORIA_CC_OLA4.md (D1–D8)', 'rol', 'CONTEXT', 'promocion_fecha', '2026-11-24', 'promocion_ola', 'OLA4')
  WHERE ingest_batch = 'OLA4_CC_2014_01' AND id IN ('OLA4_CC_2014_01:CODIGO_CIVIL:2322');
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA4_CC_2014_01' AND revision_pendiente = false AND metadata->>'estado_v' = 'V5';
  IF n <> 2372 THEN RAISE EXCEPTION 'postcondición visibles V5 = % (esperado 2372)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA4_CC_2014_01' AND es_norma_vigente = true AND NOT (metadata ? 'rol');
  IF n <> 1992 THEN RAISE EXCEPTION 'postcondición PRIMARY vigentes = % (esperado 1992)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA4_CC_2014_01' AND es_norma_vigente = true AND metadata->>'rol' = 'CONTEXT';
  IF n <> 0 THEN RAISE EXCEPTION 'postcondición CONTEXT vigentes = % (esperado 0)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA4_CC_2014_01' AND es_norma_vigente = false AND metadata->>'rol' = 'CONTEXT';
  IF n <> 378 THEN RAISE EXCEPTION 'postcondición CONTEXT derogados = % (esperado 378)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA4_CC_2014_01' AND es_norma_vigente IS NULL AND metadata->>'rol' = 'CONTEXT';
  IF n <> 2 THEN RAISE EXCEPTION 'postcondición CONTEXT pendientes = % (esperado 2)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA4_CC_2014_01' AND es_norma_vigente = false AND NOT (metadata ? 'rol');
  IF n <> 0 THEN RAISE EXCEPTION 'postcondición derogados PRIMARY (prohibido) = % (esperado 0)', n; END IF;
  UPDATE public.biblioteca_vectores b SET revision_pendiente = true,
    metadata = b.metadata || jsonb_build_object('sustituido_por_lote', 'OLA4_CC_2014_01', 'sustituido_fecha', '2026-11-24', 'revision_pendiente_motivo', 'Sustituida por HN:CODIGO_CIVIL V5 (OLA4); oculta, no borrada')
  WHERE b.metadata->>'norm_id' = 'HN_CODIGO_CIVIL_1906' AND b.id LIKE 'mayalex_normativos:cc_1906_a%' AND b.revision_pendiente = false;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 2372 THEN RAISE EXCEPTION 'legacy ocultadas: % (esperadas 2372)', n; END IF;
END $do$;
COMMIT;
SELECT count(*) AS filas, count(*) FILTER (WHERE revision_pendiente = false) AS visibles, metadata->>'estado_v' AS estado_v,
  count(*) FILTER (WHERE es_norma_vigente = true AND NOT (metadata ? 'rol')) AS primary_vigentes,
  count(*) FILTER (WHERE metadata->>'rol' = 'CONTEXT') AS context,
  count(*) FILTER (WHERE es_norma_vigente = false) AS derogados,
  count(*) FILTER (WHERE embedding IS NOT NULL) AS con_embedding,
  count(*) FILTER (WHERE encode(sha256(convert_to(contenido, 'UTF8')), 'hex') = hash_contenido) AS sha_ok
FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA4_CC_2014_01' GROUP BY metadata->>'estado_v';
